-- GENERATED by src/conditions.py

DROP VIEW IF EXISTS z_readings; DROP TABLE IF EXISTS norm_stats, readings_cond, op_conditions CASCADE;
CREATE TABLE op_conditions (cond integer PRIMARY KEY, c1 real, c2 real, c3 real);
INSERT INTO op_conditions VALUES (0,0.001507,0.000495,100.000000),(1,10.002981,0.250499,100.000000),(2,20.002986,0.700510,100.000000),(3,25.003046,0.620503,60.000000),(4,35.003038,0.840504,100.000000),(5,42.002982,0.840490,100.000000);

-- every reading + its operating condition (nearest centroid in scaled op-setting space)
CREATE TABLE readings_cond AS
SELECT r.engine_id, e.dataset, e.split, e.fold, r.cycle,
       CASE WHEN e.dataset IN ('FD001','FD003') THEN 0 ELSE c.cond END AS cond,
       r.op_setting_1, r.op_setting_2, r.op_setting_3,
       r.s1, r.s2, r.s3, r.s4, r.s5, r.s6, r.s7, r.s8, r.s9, r.s10, r.s11, r.s12, r.s13, r.s14, r.s15, r.s16, r.s17, r.s18, r.s19, r.s20, r.s21
FROM sensor_readings r
JOIN engines e USING (engine_id)
LEFT JOIN LATERAL (
   SELECT cond FROM op_conditions oc
   ORDER BY power((r.op_setting_1 - oc.c1)/42.0,2) + power((r.op_setting_2 - oc.c2)/0.84,2)
          + power((r.op_setting_3 - oc.c3)/100.0,2) LIMIT 1) c ON TRUE;
ALTER TABLE readings_cond ADD PRIMARY KEY (engine_id, cycle);
CREATE INDEX ON readings_cond (dataset, cond);

-- per-condition normalization statistics from fit-fold engines only (no leakage)
CREATE TABLE norm_stats AS
SELECT dataset, cond, count(*) AS n,
  avg(s1) AS m_s1, stddev_samp(s1) AS sd_s1,
  avg(s2) AS m_s2, stddev_samp(s2) AS sd_s2,
  avg(s3) AS m_s3, stddev_samp(s3) AS sd_s3,
  avg(s4) AS m_s4, stddev_samp(s4) AS sd_s4,
  avg(s5) AS m_s5, stddev_samp(s5) AS sd_s5,
  avg(s6) AS m_s6, stddev_samp(s6) AS sd_s6,
  avg(s7) AS m_s7, stddev_samp(s7) AS sd_s7,
  avg(s8) AS m_s8, stddev_samp(s8) AS sd_s8,
  avg(s9) AS m_s9, stddev_samp(s9) AS sd_s9,
  avg(s10) AS m_s10, stddev_samp(s10) AS sd_s10,
  avg(s11) AS m_s11, stddev_samp(s11) AS sd_s11,
  avg(s12) AS m_s12, stddev_samp(s12) AS sd_s12,
  avg(s13) AS m_s13, stddev_samp(s13) AS sd_s13,
  avg(s14) AS m_s14, stddev_samp(s14) AS sd_s14,
  avg(s15) AS m_s15, stddev_samp(s15) AS sd_s15,
  avg(s16) AS m_s16, stddev_samp(s16) AS sd_s16,
  avg(s17) AS m_s17, stddev_samp(s17) AS sd_s17,
  avg(s18) AS m_s18, stddev_samp(s18) AS sd_s18,
  avg(s19) AS m_s19, stddev_samp(s19) AS sd_s19,
  avg(s20) AS m_s20, stddev_samp(s20) AS sd_s20,
  avg(s21) AS m_s21, stddev_samp(s21) AS sd_s21
FROM readings_cond WHERE fold = 'fit' GROUP BY dataset, cond;
ALTER TABLE norm_stats ADD PRIMARY KEY (dataset, cond);

CREATE VIEW z_readings AS
SELECT r.engine_id, r.dataset, r.split, r.fold, r.cycle, r.cond,
  (r.s1 - n.m_s1) / NULLIF(n.sd_s1, 0) AS z_s1,
  (r.s2 - n.m_s2) / NULLIF(n.sd_s2, 0) AS z_s2,
  (r.s3 - n.m_s3) / NULLIF(n.sd_s3, 0) AS z_s3,
  (r.s4 - n.m_s4) / NULLIF(n.sd_s4, 0) AS z_s4,
  (r.s5 - n.m_s5) / NULLIF(n.sd_s5, 0) AS z_s5,
  (r.s6 - n.m_s6) / NULLIF(n.sd_s6, 0) AS z_s6,
  (r.s7 - n.m_s7) / NULLIF(n.sd_s7, 0) AS z_s7,
  (r.s8 - n.m_s8) / NULLIF(n.sd_s8, 0) AS z_s8,
  (r.s9 - n.m_s9) / NULLIF(n.sd_s9, 0) AS z_s9,
  (r.s10 - n.m_s10) / NULLIF(n.sd_s10, 0) AS z_s10,
  (r.s11 - n.m_s11) / NULLIF(n.sd_s11, 0) AS z_s11,
  (r.s12 - n.m_s12) / NULLIF(n.sd_s12, 0) AS z_s12,
  (r.s13 - n.m_s13) / NULLIF(n.sd_s13, 0) AS z_s13,
  (r.s14 - n.m_s14) / NULLIF(n.sd_s14, 0) AS z_s14,
  (r.s15 - n.m_s15) / NULLIF(n.sd_s15, 0) AS z_s15,
  (r.s16 - n.m_s16) / NULLIF(n.sd_s16, 0) AS z_s16,
  (r.s17 - n.m_s17) / NULLIF(n.sd_s17, 0) AS z_s17,
  (r.s18 - n.m_s18) / NULLIF(n.sd_s18, 0) AS z_s18,
  (r.s19 - n.m_s19) / NULLIF(n.sd_s19, 0) AS z_s19,
  (r.s20 - n.m_s20) / NULLIF(n.sd_s20, 0) AS z_s20,
  (r.s21 - n.m_s21) / NULLIF(n.sd_s21, 0) AS z_s21
FROM readings_cond r JOIN norm_stats n USING (dataset, cond);
ANALYZE readings_cond;
